def verify_slo(budget: dict[str, int], p95_limit_ms: int = 200) -> int:
    total = sum(budget.values())
    if total > p95_limit_ms:
        raise ValueError(f'Budget {total}ms exceeds p95 SLO {p95_limit_ms}ms')
    return p95_limit_ms - total

def estimate_tier_memory_gb(num_vectors: int, dims: int, sq_bytes: int, hnsw_m: int = 16) -> dict[str, float]:
    if num_vectors <= 0 or dims <= 0:
        raise ValueError('Vector count and dimensions must be positive')
    vec_gb = (num_vectors * dims * sq_bytes) / 1e9
    graph_gb = (num_vectors * hnsw_m * 2 * 4) / 1e9
    return {'vectors_gb': round(vec_gb, 2), 'hnsw_graph_gb': round(graph_gb, 2), 'raw_total_gb': round(vec_gb + graph_gb, 2)}

from dataclasses import dataclass
from typing import Optional

@dataclass
class SearchRequest:
    query_id: str
    modality: str
    text_query: Optional[str] = None
    top_k: int = 20
    rerank_depth: int = 200
    rrf_k: float = 60.0

    def validate(self) -> None:
        if self.top_k <= 0 or self.rerank_depth < self.top_k:
            raise ValueError('rerank_depth must be >= top_k > 0')
        if self.modality == 'TEXT' and not self.text_query:
            raise ValueError('TEXT modality requires text_query')

def assemble_dynamic_batch(queue: list, max_batch: int = 128) -> list:
    if max_batch <= 0:
        raise ValueError('max_batch must be positive')
    batch = queue[:max_batch]
    del queue[:max_batch]
    return batch

def should_hedge_shard(elapsed_ms: float, p95_shard_ms: float = 18.0) -> bool:
    if elapsed_ms < 0:
        raise ValueError('Elapsed time cannot be negative')
    return elapsed_ms > p95_shard_ms

def collapse_temporal_windows(hits: list[dict], window_sec: float = 5.0) -> list[dict]:
    if not hits:
        return []
    ordered = sorted(hits, key=lambda h: (h['video_id'], h['t']))
    collapsed = []
    for hit in ordered:
        if collapsed and collapsed[-1]['video_id'] == hit['video_id'] and (hit['t'] - collapsed[-1]['t_end']) <= window_sec:
            cur = collapsed[-1]
            cur['t_end'] = max(cur['t_end'], hit['t'])
            if hit['score'] > cur['score']:
                cur['score'] = hit['score']
                cur['keyframe_id'] = hit['keyframe_id']
        else:
            collapsed.append({'video_id': hit['video_id'], 'keyframe_id': hit['keyframe_id'], 'score': hit['score'], 't_start': hit['t'], 't_end': hit['t']})
    return sorted(collapsed, key=lambda h: h['score'], reverse=True)

def select_rerank_depth(current_qps: int, peak_qps: int = 15000) -> int:
    if current_qps < 0:
        raise ValueError('QPS must be non-negative')
    if current_qps > int(peak_qps * 1.3):
        return 50
    if current_qps > peak_qps:
        return 100
    return 200
